private void checkFields(final Class<?> type) {
    if (type == null) return;

    // NB: Reject abstract classes.
    if (Modifier.isAbstract(type.getModifiers())) {
        problems.add(new ValidityProblem("Delegate class is abstract"));
    }

    final List<Field> fields = ClassUtils.getAnnotatedFields(type, Parameter.class);

    for (final Field f : fields) {
        f.setAccessible(true); // expose private fields

        final Parameter param = f.getAnnotation(Parameter.class);

        boolean valid = true;

        // Skip types handled by the application framework itself.
        if (Service.class.isAssignableFrom(f.getType())) continue;
        if (Context.class.isAssignableFrom(f.getType())) continue;

        // Remaining validation logic
        // (code for final, isMessage, inputMap, outputMap, presets, etc.)

        if (!valid) {
            // NB: Skip invalid parameters.
            continue;
        }

        final boolean isPreset = presets.containsKey(f.getName());

        // add item to the relevant list (inputs or outputs)
        final CommandModuleItem<Object> item = new CommandModuleItem<>(this, f);
        if (item.isInput()) {
            inputMap.put(f.getName(), item);
            if (!isPreset) inputList.add(item);
        }
        if (item.isOutput()) {
            outputMap.put(f.getName(), item);
            if (!isPreset) outputList.add(item);
        }
    }
}

